//! Optional compile-time embedded model support (feature `embed-model`).
//!
//! `build.rs` reads `LLMLIP_EMBED_MODEL` (a converted `.e3rs` model directory)
//! and bakes every file in it into the binary via `include_bytes!`. The default
//! filesystem runtime (`LlmlipModel::load(path)`) is unaffected; this module
//! only adds `LlmlipModel::load_embedded()` for the self-contained build.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::model::{LlmlipModel, ModelError};

// Generated by build.rs: defines `EMBEDDED_MODEL_PRESENT: bool` and
// `EMBEDDED_MODEL_FILES: &[(&str, &[u8])]`.
include!(concat!(env!("OUT_DIR"), "/embedded_model.rs"));

/// Files of the embedded `.e3rs` model as `(relative_path, bytes)` pairs.
///
/// Empty when no model was embedded at build time.
#[must_use]
pub fn embedded_model_files() -> &'static [(&'static str, &'static [u8])] {
    EMBEDDED_MODEL_FILES
}

/// Whether a model was baked into the binary at build time via
/// `LLMLIP_EMBED_MODEL`.
#[must_use]
pub fn is_embedded_model_present() -> bool {
    EMBEDDED_MODEL_PRESENT
}

impl LlmlipModel {
    /// Load the model baked into the binary at compile time.
    ///
    /// Requires building with `--features embed-model` and `LLMLIP_EMBED_MODEL`
    /// set to a converted `.e3rs` directory. The embedded files are unpacked to
    /// a unique temporary directory, loaded with the standard loader, and the
    /// temporary directory is then removed.
    ///
    /// # Errors
    /// Returns an error if no model was embedded, if the temporary unpacking
    /// fails, or if the embedded model fails to load.
    pub fn load_embedded() -> Result<Self, ModelError> {
        if !EMBEDDED_MODEL_PRESENT {
            return Err(ModelError::InvalidManifest(
                "no model was embedded at build time; build with feature \
                 `embed-model` and set LLMLIP_EMBED_MODEL to a `.e3rs` directory"
                    .to_owned(),
            ));
        }
        let dir = unique_temp_dir();
        let result = unpack_and_load(&dir);
        // Best-effort cleanup; the loaded model owns its data by this point.
        let _ = std::fs::remove_dir_all(&dir);
        result
    }
}

fn unpack_and_load(dir: &Path) -> Result<LlmlipModel, ModelError> {
    for (rel, bytes) in EMBEDDED_MODEL_FILES {
        let dest = dir.join(rel);
        if let Some(parent) = dest.parent() {
            std::fs::create_dir_all(parent).map_err(|source| ModelError::Io {
                path: parent.to_path_buf(),
                source,
            })?;
        }
        std::fs::write(&dest, bytes).map_err(|source| ModelError::Io {
            path: dest.clone(),
            source,
        })?;
    }
    LlmlipModel::load(dir)
}

fn unique_temp_dir() -> PathBuf {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seq = COUNTER.fetch_add(1, Ordering::Relaxed);
    std::env::temp_dir().join(format!(
        "llmlip-embedded-{}-{nanos}-{seq}",
        std::process::id()
    ))
}
